import{_ as s,o as i,c as e,a3 as t}from"./chunks/framework.CVt6dz2a.js";const g=JSON.parse('{"title":"EP.12 自定义着色器 GLSL","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.12-custom-shader.md","filePath":"comics/EP.12-custom-shader.md","lastUpdated":1793881879000}'),l={name:"comics/EP.12-custom-shader.md"};function n(r,a,o,h,d,p){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="ep-12-自定义着色器-glsl" tabindex="-1">EP.12 自定义着色器 GLSL <a class="header-anchor" href="#ep-12-自定义着色器-glsl" aria-label="Permalink to &quot;EP.12 自定义着色器 GLSL&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/12-shader/basics">12.1 基础入门：GLSL 与第一个自定义着色器</a> 延伸阅读：<a href="./../guide/12-shader/advanced">进阶篇</a> · <a href="./../guide/12-shader/practice">实战篇</a> 动手演示：<a href="./../public/demos/shader/first-shader.html">first-shader 第一个自定义着色器</a> · <a href="./../public/demos/shader/uniforms-playground.html">uniforms-playground 调参游乐场</a> · <a href="./../public/demos/shader/hologram-scan.html">hologram-scan 扫描线与全息投影</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱照着教程写下人生第一段 GLSL，刷新页面却只剩一片黑——没有报错弹窗、没有红色提示，球直接消失。</td></tr><tr><td>② 揭秘</td><td>码叔打开浏览器控制台，指着 <code>THREE.WebGLProgram: Shader Error</code> 报错块：冒号中间的数字就是出错行号，对着源码数行就能定位。</td></tr><tr><td>③ 实证</td><td>逐行排查揪出两个经典杀手：片元里混进的全角分号 <code>；</code> 和一句中文注释。改成英文半角后，法线渐变球应声点亮。</td></tr><tr><td>④ 结案</td><td>码叔总结 GLSL 三铁律：只写英文半角、行号看控制台、中间结果画成颜色当调试。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-着色器黑屏-js-报错" tabindex="-1">① 着色器黑屏 ≠ JS 报错 <a class="header-anchor" href="#_1-着色器黑屏-js-报错" aria-label="Permalink to &quot;① 着色器黑屏 ≠ JS 报错&quot;">​</a></h3><p><code>ShaderMaterial</code> 的 GLSL 源码是一段字符串，<strong>JS 引擎不会检查它</strong>——字符串能正常创建，语法错误要到 GPU 编译阶段才暴露。表现就是：页面不崩、控制台没有 JS 异常、但物体不渲染（黑屏/消失）。所以写 shader 的第一反应不是刷新重试，而是<strong>打开控制台找编译日志</strong>。</p><h3 id="_2-控制台上的-three-webglprogram-报错" tabindex="-1">② 控制台上的 THREE.WebGLProgram 报错 <a class="header-anchor" href="#_2-控制台上的-three-webglprogram-报错" aria-label="Permalink to &quot;② 控制台上的 THREE.WebGLProgram 报错&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>THREE.WebGLProgram: Shader Error 0 - VALIDATE_STATUS false</span></span>
<span class="line"><span>  ERROR: 0:15: &#39;；&#39; : unexpected token</span></span></code></pre></div><ul><li><code>0:15</code> 中第二个数字 <strong>15 是出错行号</strong>（从该段着色器源码第 1 行数起）；</li><li>报错块下方还会打印完整源码，行号可能因引擎注入的前置声明偏移几行，在附近找拼写/符号错误即可。</li></ul><h3 id="_3-两个新手杀手-全角标点与中文注释" tabindex="-1">③ 两个新手杀手：全角标点与中文注释 <a class="header-anchor" href="#_3-两个新手杀手-全角标点与中文注释" aria-label="Permalink to &quot;③ 两个新手杀手：全角标点与中文注释&quot;">​</a></h3><p>GLSL 编译器按 <strong>ASCII</strong> 解析源码：</p><ul><li>全角分号 <code>；</code>、全角括号 <code>（）</code>、中文逗号 <code>，</code> 都是非法记号；</li><li>中文注释文字同样非法——<code>/* glsl */</code> 模板字符串里<strong>只允许英文 + 半角符号</strong>；</li><li>中文解释请写在 GLSL 字符串<strong>外面</strong>的 JS 注释里。</li></ul><h3 id="_4-修复链路-法线渐变球" tabindex="-1">④ 修复链路：法线渐变球 <a class="header-anchor" href="#_4-修复链路-法线渐变球" aria-label="Permalink to &quot;④ 修复链路：法线渐变球&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> vertexShader</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* glsl */</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  varying vec3 vNormal;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  void main() {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    vNormal = normal;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fragmentShader</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* glsl */</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  varying vec3 vNormal;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  void main() {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    vec3 color = normalize(vNormal) * 0.5 + 0.5;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    gl_FragColor = vec4(color, 1.0);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ShaderMaterial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ vertexShader, fragmentShader })</span></span></code></pre></div><p>顶点阶段递出法线，光栅化自动插值，片元阶段归一化后映射到 0~1 当颜色——无需灯光，球面随视角转动呈现连续的红绿蓝渐变。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：黑屏了第一步做什么？</strong> F12 打开控制台，搜 <code>THREE.WebGLProgram</code>，报错里的行号直接定位问题。</li><li><strong>Q：报错行号和源码对不上？</strong> 引擎会在你的源码前注入内置声明，行号可能偏移几行，上下找即可。</li><li><strong>Q：GLSL 里能写中文注释吗？</strong> 不能。编译器只认 ASCII，中文与全角标点都会编译失败；注释一律英文。</li><li><strong>Q：片元着色器必须写 precision 吗？</strong> <code>ShaderMaterial</code> 默认注入 <code>precision mediump float;</code> 无需手写；RawShaderMaterial 或独立 .glsl 文件必须显式声明。</li><li><strong>Q：shader 里怎么调试中间值？</strong> 没有 console.log，把变量塞进颜色输出：<code>gl_FragColor = vec4(vec3(myValue), 1.0);</code>，用眼睛看。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li><code>ShaderMaterial</code> 渲染黑屏但页面没有任何 JS 报错，原因是什么？第一步排查动作是什么？</li><li>控制台报错 <code>ERROR: 0:23: &#39;；&#39; : unexpected token</code>，最可能的原因是什么？</li><li>为什么 GLSL 字符串里写中文注释会导致编译失败，而写在字符串外的 JS 注释就没事？</li></ol><details><summary>答案</summary><ol><li>GLSL 源码是字符串，语法错误只在 <strong>GPU 编译阶段</strong>暴露，不经过 JS 异常机制，所以页面不崩但物体不渲染。第一步：打开控制台找 <strong><code>THREE.WebGLProgram: Shader Error</code></strong>，按报错行号定位。</li><li>该行混入了<strong>全角分号 <code>；</code></strong>（或其它全角/中文字符）。GLSL 只接受 ASCII 半角符号，逐个检查该行的标点即可。</li><li>GLSL 编译器按 ASCII 解析，中文字符是非法记号；而字符串外的 JS 注释由 <strong>JS 引擎</strong>处理，天然支持 Unicode，互不相干。规则：GLSL 内只写英文，中文解释放 JS 注释里。</li></ol></details>`,21)])])}const k=s(l,[["render",n]]);export{g as __pageData,k as default};
